            $com_enviada = ComEnviadaPeer::retrieveByPk(trim($this->getRequestParameter('comenviada_id')));
            $interesado_com = EnviadaInteresadosPeer::retrieveByPk(trim($this->getRequestParameter('interesadocom_id')));
