        } catch (\Exception $ex) {
            $response_data = array( 'status' => 400, 'message' => $ex->getMessage());
        }
        //****************************************************************************************************
        $array = json_encode($response_data);
        $this->getResponse()->setContentType('application/json');      
        return $this->renderText($array);
    }

