            if($res->getRolusComenviadaId()==1){
                $this->creador = $res->getUsuarioId();
                $this->creador_name = $res->getUsuario()->getNombre()." ".$res->getUsuario()->getApellido();
            }elseif($res->getRolusComenviadaId()==2){
                $this->firmante .= $res->getUsuarioId().",";
