            $dataRow['COD_DEPENDENCIA'] = trim($row[2]);
            $dataRow['ASUNTO_COM'] = trim($row[3]);
            $dataRow['NUM_FOLIOS'] = trim($row[4]);
            $dataRow['TIPO_DOCUMENTO'] = trim($row[5]);
            $dataRow['OBSERVACIONES_COM'] = trim($row[6]);
            $dataRow['NOMBRE_ARCHIVO'] = trim($row[7]);
            $dataRow['RADICADO_ENTRADA'] = trim($row[8]);
            $dataRow['FIRMA_DIGITAL'] = $row[9] == "SI" ? 1 : 0;
            $dataRow['TIPO_NOTIFICACION'] = trim($row[10]);
            $dataRow['NUMERO_EXPEDIENTE'] = trim($row[11]);
            $dataRow['NUMERO_FUD'] = trim($row[12]);
            $dataRow['FECHA_RESOLUCION'] = trim($row[13]);
            $dataRow['NUMERO_RESOLUCION'] = trim($row[14]);
            $dataRow['COD_TIPO_DOC'] = trim($row[15]);
            $dataRow['ID_SUBORIGEN'] = trim($row[16]);
            $dataRow['PNOMBRE_INTERESADO'] = trim($row[17]);
            $dataRow['SNOMBRE_INTERESADO'] = trim($row[18]);
            $dataRow['PAPELLIDO_INTERESADO'] = trim($row[19]);
            $dataRow['SAPELLIDO_INTERESADO'] = trim($row[20]);
            $dataRow['NUID_INTERESADO'] = trim($row[21]);
            $dataRow['NUIDS_FIRMAS'] = trim($row[22]);
            $dataRow['NIT_DESTINATARIO'] = trim($row[23]);
            $dataRow['RAZON_SOCIAL'] = trim($row[24]);
