        $this->guardarAuditoria($com_enviada_anterior,$com_enviada);
		//********************************************************************************
        return $this->redirect($this->getRequest()->getScriptName().'/com_enviada/show?comenviada_id='.$com_enviada->getPrimaryKey());
    }
   
